class Solution:
    def findTrack(self, playlist: List[int], target: int) -> int:
        a, n = playlist, len(playlist)
        lo, hi = 0, n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] > a[hi]:
                lo = mid + 1
            else:
                hi = mid
        p = lo
        lo, hi = (p, n - 1) if a[p] <= target <= a[n - 1] else (0, p - 1)
        while lo <= hi:
            mid = (lo + hi) // 2
            if a[mid] == target:
                return mid
            if a[mid] < target:
                lo = mid + 1
            else:
                hi = mid - 1
        return -1

