class Solution {
    public int findTrack(int[] a, int target) {
        int n = a.length, lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] > a[hi]) lo = mid + 1; else hi = mid;
        }
        int p = lo;
        if (a[p] <= target && target <= a[n - 1]) { lo = p; hi = n - 1; }
        else { lo = 0; hi = p - 1; }
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] == target) return mid;
            if (a[mid] < target) lo = mid + 1; else hi = mid - 1;
        }
        return -1;
    }
}

