class Solution {
public:
    int findTrack(vector<int>& a, int target) {
        int n = a.size(), lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (a[mid] > a[hi]) lo = mid + 1; else hi = mid;
        }
        int p = lo;
        auto first = (a[p] <= target && target <= a[n - 1]) ? a.begin() + p : a.begin();
        auto last = (a[p] <= target && target <= a[n - 1]) ? a.end() : a.begin() + p;
        auto it = lower_bound(first, last, target);
        return (it != last && *it == target) ? (int) (it - a.begin()) : -1;
    }
};

